import { ImageResponse } from "next/og";
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { Params } from "@/lib/utils";
import { getTierOnePageData } from "../actions/getTierPageData";
import { asImageSrc } from "@prismicio/client";

// Image metadata
export const alt = "American Correctional Association";
export const size = {
  width: 2400,
  height: 1260,
};

export const contentType = "image/png";

// Image generation
export default async function OpenGraphImage({
  params,
}: {
  params: Promise<Params>;
}) {
  const { tier_one_uid } = await params;

  const pageData = await getTierOnePageData(tier_one_uid).catch(() => null);

  if (pageData?.data.meta_image?.url) {
    return new ImageResponse(
      (
        <div
          style={{
            height: "100%",
            width: "100%",
            display: "flex",
          }}
        >
          <img
            src={asImageSrc(pageData.data.meta_image) ?? ""}
            alt={
              pageData.data.pageImage.alt ??
              "ACA - American Correctional Association"
            }
            style={{
              objectFit: "cover",
              width: "100%",
              height: "100%",
            }}
          />
        </div>
      ),
      {
        ...size,
      }
    );
  }

  const gillSansBold = await readFile(
    join(process.cwd(), "public", "gs-bold.otf")
  );

  return new ImageResponse(
    (
      <div
        style={{
          height: "100%",
          width: "100%",
          display: "flex",
          position: "relative",
          background: "linear-gradient(90deg, #142E53 0%, #0E376C 100%)",
        }}
      >
        <div
          style={{
            display: "flex",
            position: "absolute",
            top: "122px",
            left: "95px",
          }}
        >
          <ACALogo />
        </div>
        <div
          style={{
            display: "flex",
            position: "absolute",
            top: "0",
            right: "0",
          }}
        >
          <Squares />
        </div>
        <div
          style={{
            position: "absolute",
            display: "flex",
            top: "50%",
            left: "95px",
            fontSize: 160,
            fontWeight: 700,
            fontFamily: "Gill Sans",
            color: "white",
            lineHeight: 1.2,
            zIndex: 20,
            transform: "translateY(-75%)",
            width: "75%",
          }}
        >
          {pageData?.data.meta_title ||
            pageData?.data.pageTitle ||
            `American Correctional Association`}
        </div>
        {/* <Background /> */}
      </div>
    ),
    {
      fonts: [
        {
          name: "Gill Sans",
          data: gillSansBold,
          style: "normal",
          weight: 700,
        },
      ],
      ...size,
    }
  );
}

